static uintptr_t mappedModule(DWORD pid,const wchar_t* name){HANDLE process=OpenProcess(PROCESS_QUERY_INFORMATION|PROCESS_VM_READ,FALSE,pid);if(!process)return 0;MEMORY_BASIC_INFORMATION mbi={};uintptr_t result=0;for(uint64_t address=0;address<0x100000000ULL;){if(!VirtualQueryEx(process,(void*)(uintptr_t)address,&mbi,sizeof(mbi)))break;uint64_t next=(uint64_t)(uintptr_t)mbi.BaseAddress+mbi.RegionSize;if(next<=address)break;if(mbi.Type==MEM_IMAGE&&mbi.BaseAddress==mbi.AllocationBase){wchar_t path[32768];if(GetMappedFileNameW(process,mbi.AllocationBase,path,32768)){const wchar_t* b=wcsrchr(path,L'\\');if(b&&!_wcsicmp(b+1,name)){result=(uintptr_t)mbi.AllocationBase;break;}}}address=next;}CloseHandle(process);return result;}
static uintptr_t remoteModule(DWORD pid,const wchar_t* name){HANDLE snapshot=CreateToolhelp32Snapshot(TH32CS_SNAPMODULE|TH32CS_SNAPMODULE32,pid);if(snapshot==INVALID_HANDLE_VALUE)return mappedModule(pid,name);MODULEENTRY32W m={sizeof(m)};uintptr_t result=0;if(Module32FirstW(snapshot,&m))do{if(!_wcsicmp(m.szModule,name)){result=(uintptr_t)m.modBaseAddr;break;}}while(Module32NextW(snapshot,&m));CloseHandle(snapshot);return result?result:mappedModule(pid,name);}
static uintptr_t remoteFunction(DWORD pid,HMODULE module,const char* name){FARPROC address=GetProcAddress(module,name);if(!address)return 0;MEMORY_BASIC_INFORMATION mbi={};if(!VirtualQuery(address,&mbi,sizeof(mbi)))return 0;wchar_t path[32768];if(!GetModuleFileNameW((HMODULE)mbi.AllocationBase,path,32768))return 0;const wchar_t* base=wcsrchr(path,L'\\');uintptr_t remote=remoteModule(pid,base?base+1:path);return remote?remote+(uintptr_t)address-(uintptr_t)mbi.AllocationBase:0;}
static bool remoteCall(HANDLE process,uintptr_t function,void* argument,DWORD& result){HANDLE thread=CreateRemoteThread(process,0,0,(LPTHREAD_START_ROUTINE)function,argument,0,0);if(!thread)return false;bool ok=WaitForSingleObject(thread,15000)==WAIT_OBJECT_0&&GetExitCodeThread(thread,&result);CloseHandle(thread);return ok;}
static bool installRenderer(HANDLE process,DWORD pid,const wchar_t* path,DWORD& code){code=1;HMODULE image=LoadLibraryExW(path,0,DONT_RESOLVE_DLL_REFERENCES);if(!image)return false;auto entry=GetProcAddress(image,"_N2HD_RemoteInstall@4");if(!entry){FreeLibrary(image);code=2;return false;}uintptr_t offset=(uintptr_t)entry-(uintptr_t)image;FreeLibrary(image);uintptr_t load=remoteFunction(pid,GetModuleHandleW(L"kernel32.dll"),"LoadLibraryW");if(!load){uintptr_t bootstrap=remoteFunction(pid,GetModuleHandleW(L"ntdll.dll"),"RtlExitUserThread");DWORD bootCode=0;if(!bootstrap||!remoteCall(process,bootstrap,0,bootCode)){code=30;return false;}load=remoteFunction(pid,GetModuleHandleW(L"kernel32.dll"),"LoadLibraryW");if(!load){code=3;return false;}}size_t bytes=(wcslen(path)+1)*sizeof(wchar_t);void* remote=VirtualAllocEx(process,0,bytes,MEM_RESERVE|MEM_COMMIT,PAGE_READWRITE);if(!remote){code=4;return false;}SIZE_T written=0;DWORD module=0;bool ok=WriteProcessMemory(process,remote,path,bytes,&written)&&written==bytes&&remoteCall(process,load,remote,module)&&module;VirtualFreeEx(process,remote,0,MEM_RELEASE);if(!ok){code=5;return false;}DWORD installed=0;ok=remoteCall(process,(uintptr_t)module+offset,0,installed)&&installed==1;code=ok?0:6;return ok;}
